  thumbnail?: string;
  articleClass?: string;
  includeExcerpt?: boolean;
  slug?: string;
  seo?: {
    pageType?: "article" | "website" | "collection" | "profile" | "contact" | "confirmation";
    publishedTime?: string;
    modifiedTime?: string;
  };
}

const {
  title,
  description,
  thumbnail,
