export const SITE_NAME = "Lovely Sunday";
export const SITE_DESCRIPTION =
  "Two best friends exploring the west coast in favorite outfits, sharing fashion-led photography, lookbooks, and travel diaries.";
export const SITE_SHORT_DESCRIPTION =
  "Fashion-led visual stories, lookbooks, and travel diaries from Aileen and Rory.";
export const SITE_AUTHOR = "Lovely Sunday";
export const SITE_ALTERNATE_NAME = "LovelySunday";
export const SITE_CATEGORY = "Fashion and lifestyle editorial";
export const SITE_LOCATION = "San Francisco, CA, USA";
export const SITE_CONTACT_EMAIL = "contact@lovelysunday.co";
export const SITE_FOUNDERS = ["Aileen", "Rory"] as const;
export const SITE_SAME_AS = [
  "https://www.instagram.com/_lovelysunday/",
  "https://www.facebook.com/pages/LovelySunday/812231418844278",
] as const;
export const SITE_KNOWS_ABOUT = [
  "Fashion",
  "Style editorials",
  "Travel diaries",
  "Lookbooks",
  "Outfit inspiration",
  "Fashion photography",
  "West Coast travel",
  "Paris style",
] as const;
export const SITE_KEYWORDS = [
  "Lovely Sunday",
  "LovelySunday",
  "Aileen and Rory",
  "fashion blog",
  "style editorials",
  "travel diary",
  "lookbook",
  "outfit inspiration",
  "fashion photography",
  "west coast style",
] as const;
export const SITE_AI_META = {
  contentType: "editorial archive",
  topics: "fashion, travel, lookbooks, outfit inspiration, photography",
  audience: "search crawlers, answer engines, LLM assistants, editorial readers",
  use: "Summarize posts, cite outfit stories, and route readers back to canonical pages.",
} as const;
import {
  SITE_ALTERNATE_NAME,
  SITE_AUTHOR,
  SITE_CONTACT_EMAIL,
  SITE_DESCRIPTION,
  SITE_FOUNDERS,
  SITE_KNOWS_ABOUT,
  SITE_LOCATION,
  SITE_NAME,
  SITE_SAME_AS,
} from "./siteMeta";

export type SeoPageType =
  | "website"
  | "article"
  | "collection"
  | "profile"
  | "contact"
  | "confirmation";

export interface SeoBuildInput {
  pathname: string;
  siteOrigin: string;
  siteName: string;
  title?: string;
  description?: string;
  image?: string;
  pageType?: SeoPageType;
  publishedTime?: string;
  modifiedTime?: string;
}

const SITE_LOCALE = "en_US";
const BRAND_AUTHOR = SITE_AUTHOR;

const normalizePathname = (pathname: string): string => {
  const [pathOnly] = pathname.split("?");
  if (!pathOnly || pathOnly === "/") return "/";
  return `/${pathOnly.replace(/^\/+|\/+$/g, "")}`;
};

const slugToWords = (value: string): string =>
  value
    .replace(/[-_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const titleCase = (value: string): string =>
  value
    .split(" ")
    .filter(Boolean)
    .map((token) => token.charAt(0).toUpperCase() + token.slice(1))
    .join(" ");

const cleanDescription = (description?: string): string | undefined => {
  if (!description) return undefined;
  return description.replace(/\s+/g, " ").trim().slice(0, 160);
};

const inferDescriptionFromPath = (pathname: string, siteName: string): string => {
  if (pathname === "/") {
    return "Explore minimalist fashion editorials, lookbooks, and travel-inspired style stories on Lovely Sunday.";
  }

  const segments = pathname.split("/").filter(Boolean);
  const parent = segments[0];
  const lastSegment = segments[segments.length - 1];
  const humanized = titleCase(slugToWords(lastSegment));

  if (parent === "work") return `${humanized} — a featured style story from ${siteName}.`;
  if (parent === "news") return `${humanized} — latest updates and editorial notes from ${siteName}.`;
  if (parent === "sold") return `${humanized} — archived piece from the ${siteName} collection.`;
  if (parent === "about-lovely-sunday") return `Meet the creator behind ${siteName} and learn the story behind the editorial style.`;
  if (parent === "contact") return `Get in touch with ${siteName} for collaborations, commissions, and styling inquiries.`;

  return `${humanized} on ${siteName}.`;
};


const strategistNarrative = (pathname: string, siteName: string): string => {
  if (pathname === "/") return `Discover curated fashion editorials and visual stories from ${siteName}.`;
  const segments = pathname.split("/").filter(Boolean);
  return `Explore ${titleCase(slugToWords(segments[segments.length - 1] || "story"))} on ${siteName}.`;
};

const strategistIntent = (pathname: string, siteName: string): string => {
  if (pathname.startsWith("/contact")) return `Contact ${siteName} for collaborations, commissions, and editorial inquiries.`;
  if (pathname.startsWith("/about")) return `Learn about ${siteName}, the creative process, and the founder's style perspective.`;
  return inferDescriptionFromPath(pathname, siteName);
};

const strategistSERP = (pathname: string, siteName: string): string => {
  if (pathname.startsWith("/work/")) return `View this ${siteName} work entry featuring styling notes, imagery, and creative direction.`;
  if (pathname.startsWith("/news/")) return `Read the latest ${siteName} update with behind-the-scenes context and announcements.`;
  return inferDescriptionFromPath(pathname, siteName);
};

const blendGeneratedDescription = (pathname: string, siteName: string): string => {
  const candidates = [
    strategistNarrative(pathname, siteName),
    strategistIntent(pathname, siteName),
    strategistSERP(pathname, siteName),
  ].map((value) => cleanDescription(value) || "").filter(Boolean);

  return candidates.sort((a, b) => b.length - a.length)[0] || inferDescriptionFromPath(pathname, siteName);
};

const inferPageType = (pathname: string, pageType?: SeoPageType): SeoPageType => {
  if (pageType) return pageType;
  if (pathname === "/") return "website";
  if (pathname.startsWith("/work/") || pathname.startsWith("/news/") || pathname.startsWith("/sold/")) {
    return "article";
  }
  if (pathname === "/about-lovely-sunday") return "profile";
  if (pathname.startsWith("/contact")) return pathname.includes("thanks") ? "confirmation" : "contact";
  return "collection";
};

const breadcrumbItems = (pathname: string, siteOrigin: string) => {
  const segments = pathname.split("/").filter(Boolean);
  const crumbs = [{ name: "Home", item: new URL("/", siteOrigin).toString() }];
  let rollingPath = "";

  for (const segment of segments) {
    rollingPath += `/${segment}`;
    crumbs.push({
      name: titleCase(slugToWords(segment)),
      item: new URL(`${rollingPath}/`, siteOrigin).toString(),
    });
  }

  return crumbs;
};

export interface GeneratedSeoMeta {
  canonical: string;
  title: string;
  description: string;
  openGraphType: "website" | "article";
  robots: string;
  locale: string;
  author: string;
  jsonLd: string[];
}

export const buildSeoMeta = ({
  pathname,
  siteOrigin,
  siteName,
  title,
  description,
  image,
  pageType,
  publishedTime,
  modifiedTime,
}: SeoBuildInput): GeneratedSeoMeta => {
  const normalizedPath = normalizePathname(pathname);
  const canonical = new URL(normalizedPath === "/" ? "/" : `${normalizedPath}/`, siteOrigin).toString();
  const siteRootUrl = new URL("/", siteOrigin).toString();
  const organizationId = `${siteRootUrl}#organization`;
  const websiteId = `${siteRootUrl}#website`;
  const resolvedTitle = title?.trim() || siteName;
  const resolvedDescription =
    cleanDescription(description) || blendGeneratedDescription(normalizedPath, siteName);
  const resolvedPageType = inferPageType(normalizedPath, pageType);
  const openGraphType = resolvedPageType === "article" ? "article" : "website";
  const robots = "index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1";

  const pageSchemaTypeByKind: Record<SeoPageType, string> = {
    website: "WebSite",
    article: "Article",
    collection: "CollectionPage",
    profile: "ProfilePage",
    contact: "ContactPage",
    confirmation: "WebPage",
  };

  const pageSchema: Record<string, unknown> = {
    "@context": "https://schema.org",
    "@type": pageSchemaTypeByKind[resolvedPageType],
    name: resolvedTitle,
    description: resolvedDescription,
    url: canonical,
    inLanguage: "en-US",
    isPartOf: {
      "@type": "WebSite",
      "@id": websiteId,
      name: siteName,
      url: siteRootUrl,
    },
    about: {
      "@id": organizationId,
    },
  };

  if (image) {
    pageSchema.image = image;
  }

  if (resolvedPageType === "website") {
    pageSchema["@id"] = websiteId;
    pageSchema.publisher = { "@id": organizationId };
    pageSchema.sameAs = [...SITE_SAME_AS];
  }

  if (resolvedPageType === "article") {
    pageSchema.author = { "@id": organizationId };
    pageSchema.publisher = { "@id": organizationId };
    if (publishedTime) pageSchema.datePublished = publishedTime;
    if (modifiedTime) pageSchema.dateModified = modifiedTime;
  }

  if (resolvedPageType === "profile") {
    pageSchema.mainEntity = { "@id": organizationId };
  }

  const organizationSchema = {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": organizationId,
    name: SITE_NAME,
    alternateName: SITE_ALTERNATE_NAME,
    url: siteRootUrl,
    description: SITE_DESCRIPTION,
    email: SITE_CONTACT_EMAIL,
    foundingLocation: {
      "@type": "Place",
      name: SITE_LOCATION,
    },
    founder: SITE_FOUNDERS.map((name) => ({
      "@type": "Person",
      name,
    })),
    sameAs: [...SITE_SAME_AS],
    knowsAbout: [...SITE_KNOWS_ABOUT],
  };

  const breadcrumbs = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: breadcrumbItems(normalizedPath, siteOrigin).map((crumb, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: crumb.name,
      item: crumb.item,
    })),
  };

  return {
    canonical,
    title: resolvedTitle,
    description: resolvedDescription,
    openGraphType,
    robots,
    locale: SITE_LOCALE,
    author: BRAND_AUTHOR,
    jsonLd: [
      JSON.stringify(pageSchema),
      JSON.stringify(organizationSchema),
      JSON.stringify(breadcrumbs),
    ],
  };
};
interface RouteMetaInput {
  title?: string | null;
  canonical?: string | null;
  meta?: {
    description?: string | null;
    robots?: string | null;
  } | null;
  openGraph?: {
    title?: string | null;
    description?: string | null;
    image?: string | null;
    type?: string | null;
    url?: string | null;
  } | null;
  twitter?: {
    card?: "summary" | "summary_large_image" | "app" | "player" | null;
    title?: string | null;
    description?: string | null;
    image?: string | null;
  } | null;
  jsonLd?: string[] | null;
}

export interface RouteSeoMeta {
  title?: string;
  canonical?: string;
  description?: string;
  robots?: string;
  openGraph: {
    title?: string;
    description?: string;
    image?: string;
    type?: string;
    url?: string;
  };
  twitter: {
    card?: "summary" | "summary_large_image" | "app" | "player";
    title?: string;
    description?: string;
    image?: string;
  };
  jsonLd: string[];
}

const pageJsonModules = import.meta.glob<RouteMetaInput>("../../capture/page_json/*.json", {
  eager: true,
  import: "default",
});

const normalizePathname = (pathname: string): string => {
  const [pathOnly] = pathname.split("?");
  const collapsed = pathOnly.replace(/\/{2,}/g, "/");
  if (!collapsed || collapsed === "/") return "/";
  return collapsed.replace(/\/$/, "");
};

const normalizeLegacyUrl = (value?: string | null): string | undefined => {
  if (!value) return undefined;

  try {
    const url = new URL(value);
    if (url.protocol === "http:" && url.hostname === "www.lovelysunday.co") {
      url.protocol = "https:";
    }
    return url.toString();
  } catch {
    return value ?? undefined;
  }
};

const canonicalToPath = (canonical?: string | null): string | null => {
  if (!canonical) return null;
  try {
    return normalizePathname(new URL(canonical).pathname || "/");
  } catch {
    return null;
  }
};

/**
 * Prevent JSON-LD strings from closing a <script> tag early.
 * The HTML parser sees </script> regardless of the script's type attribute,
 * so we replace it with a safe escaped form that is valid JSON but won't
 * trigger the HTML parser.
 */
const sanitizeJsonLd = (raw: string): string =>
  raw.replace(/<\/(script)/gi, "<\\/$1");

const routeSeoByPath = new Map<string, RouteSeoMeta>();

for (const data of Object.values(pageJsonModules)) {
  const path = canonicalToPath(data.canonical) || canonicalToPath(data.openGraph?.url);
  if (!path) continue;

  const existing = routeSeoByPath.get(path);
  if (existing && existing.canonical && data.canonical) {
    continue;
  }

  routeSeoByPath.set(path, {
    title: data.title ?? undefined,
    canonical: normalizeLegacyUrl(data.canonical),
    description: data.meta?.description ?? undefined,
    robots: data.meta?.robots ?? undefined,
    openGraph: {
      title: data.openGraph?.title ?? undefined,
      description: data.openGraph?.description ?? undefined,
      image: data.openGraph?.image ?? undefined,
      type: data.openGraph?.type ?? undefined,
      url: normalizeLegacyUrl(data.openGraph?.url),
    },
    twitter: {
      card: data.twitter?.card ?? undefined,
      title: data.twitter?.title ?? undefined,
      description: data.twitter?.description ?? undefined,
      image: data.twitter?.image ?? undefined,
    },
    jsonLd: (data.jsonLd ?? [])
      .filter((entry) => !/"@context"\s*:\s*"http:\/\/schema\.org"/.test(entry))
      .map(sanitizeJsonLd),
  });
}

if (!routeSeoByPath.has("/") && routeSeoByPath.has("/index")) {
  const indexMeta = routeSeoByPath.get("/index");
  if (indexMeta) {
    routeSeoByPath.set("/", indexMeta);
  }
}

export const getRouteSeoMeta = (pathname: string): RouteSeoMeta | undefined =>
  routeSeoByPath.get(normalizePathname(pathname));

