function extractVitePlugins(raw: unknown): Plugin[] {
  if (!raw) {
    return [];
  }

  // vite.plugins accepts Plugin | Plugin[] | (Plugin | false | null | undefined)[][] etc.
  const flat = (Array.isArray(raw) ? raw : [raw]).flat(Infinity);

  return flat.filter(
